<?php
$apiDash=['total'=>0,'sent'=>0,'delivered'=>0,'failed'=>0,'queued'=>0];$apiChannelCount=0;
try{$pdo=appDb();$q=$pdo->prepare("SELECT COUNT(*) total,SUM(m.status IN ('sent','delivered','read')) sent,SUM(m.status IN ('delivered','read')) delivered,SUM(m.status IN ('failed','partial')) failed,SUM(m.status IN ('queued','pending')) queued FROM api_message_history h JOIN messages m ON m.id=h.message_id AND m.tenant_id=h.tenant_id WHERE h.tenant_id=? AND h.created_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01')");$q->execute([(int)$_SESSION['user']['tenant_id']]);$apiDash=array_merge($apiDash,$q->fetch()?:[]);$q=$pdo->prepare("SELECT COUNT(*) FROM channels WHERE tenant_id=? AND type='whatsapp' AND status='connected'");$q->execute([(int)$_SESSION['user']['tenant_id']]);$apiChannelCount=(int)$q->fetchColumn();}catch(Throwable $e){error_log('ZYNKO API dashboard: '.get_class($e));}
?>
